if getgenv().XiaoYuRageMax and getgenv().XiaoYuRageMax.Unload then
    pcall(getgenv().XiaoYuRageMax.Unload)
end
if not game:IsLoaded() then game.Loaded:Wait() end

local K = { connections = {}, cleanups = {}, destroyed = false }
getgenv().XiaoYuRageMax = K

K.Build = "2026-10-19 (24): KH gun pacing, rep root read-back, diagnostics log (hit check), rerun watchdog"
warn("[XiaoYu Rebuild] build " .. K.Build)

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local CollectionService = game:GetService("CollectionService")
local HttpService = game:GetService("HttpService")
local SoundService = game:GetService("SoundService")
local Lighting = game:GetService("Lighting")
local player = Players.LocalPlayer

K.AccountId = tostring(player.UserId)
K.AccountDir = "xiaoyurebuild/rivals/accounts/" .. K.AccountId

local rawget, rawset = rawget, rawset

function K.fn(name)
    local v
    pcall(function() v = getfenv(0)[name] end)
    if type(v) ~= "function" then pcall(function() v = getfenv()[name] end) end
    return type(v) == "function" and v or nil
end

local getthreadidentity_ = K.fn("getthreadidentity") or K.fn("getidentity")
local setthreadidentity_ = K.fn("setthreadidentity") or K.fn("setidentity")
local sethiddenproperty_ = K.fn("sethiddenproperty")
local gethui_ = K.fn("gethui")
local function identity(n)
    if not setthreadidentity_ then return function() end end
    local old = getthreadidentity_ and getthreadidentity_() or nil
    pcall(setthreadidentity_, n)
    return function() if old then pcall(setthreadidentity_, old) end end
end
K.identity = identity
local function hudParent()
    local ok, h = pcall(function() return gethui_ and gethui_() end)
    if ok and h then return h end
    return game:GetService("CoreGui")
end
K.hudParent = hudParent

function K.track(c) K.connections[#K.connections + 1] = c return c end
function K.onUnload(f) K.cleanups[#K.cleanups + 1] = f end

do
    local env = getgenv()
    local oldPcall = env.__XiaoYuOrigPcall or pcall
    env.__XiaoYuOrigPcall = oldPcall
    local S = { total = 0, keys = {}, nkeys = 0, new = {}, lines = 0, dropped = 0, busy = false }
    K.Swallowed = S
    local function describe(f)
        if type(f) ~= "function" then return "?" end
        local ok, src, line = oldPcall(debug.info, f, "sl")
        if ok then return tostring(src) .. ":" .. tostring(line) end
        return "?"
    end
    local function report(f, err)
        if S.busy then return end
        S.total += 1
        local key = type(err) == "string" and err or tostring(err)
        local e = S.keys[key]
        if e then e.n += 1 return end
        if S.nkeys >= 600 then S.dropped += 1 return end
        S.busy = true
        e = { n = 1, where = describe(f), msg = string.sub(key, 1, 300) }
        S.keys[key] = e
        S.nkeys += 1
        S.new[#S.new + 1] = e
        S.busy = false
    end
    local function finish(f, ok, ...)
        if not ok then report(f, (...)) end
        return ok, ...
    end
    local function wrapped(f, ...)
        return finish(f, oldPcall(f, ...))
    end
    env.pcall = wrapped
    K.onUnload(function()
        if env.pcall == wrapped then env.pcall = oldPcall end
    end)
end

do
    local wrf, apf, rdf = K.fn("writefile"), K.fn("appendfile"), K.fn("readfile")
    local isf, isd, mkf = K.fn("isfile"), K.fn("isfolder"), K.fn("makefolder")
    local lsf, dlf = K.fn("listfiles"), K.fn("delfile")
    local dir = "xiaoyurebuild/logs"
    if mkf then
        for _, p in ipairs({ "xiaoyurebuild", dir }) do
            pcall(function() if not (isd and isd(p)) then mkf(p) end end)
        end
    end

    local uid = tostring(player.UserId)
    local t0 = tick()
    local path = string.format("%s/session_%s_%s.log", dir, uid, os.date("%Y%m%d_%H%M%S"))
    local statePath = string.format("%s/state_%s.json", dir, uid)
    local reportPath = dir .. "/crash_reports.log"
    local lineCount, maxLines = 0, 4000
    local canWrite = (apf ~= nil) or (wrf ~= nil and rdf ~= nil and isf ~= nil)

    local function append(file, text)
        if apf then
            pcall(apf, file, text)
        elseif canWrite then

            local old = ""
            pcall(function() if isf(file) then old = rdf(file) end end)
            pcall(wrf, file, old .. text)
        end
    end

    local crumbs = {}
    function K.Crumb(text)
        crumbs[#crumbs + 1] = os.date("%H:%M:%S ") .. string.sub(tostring(text), 1, 160)
        if #crumbs > 16 then table.remove(crumbs, 1) end
    end

    function K.Log(level, msg)
        if level ~= "beat" then K.Crumb(tostring(level) .. ": " .. tostring(msg)) end
        if lineCount >= maxLines or not canWrite then return end
        lineCount += 1
        append(path, string.format("[%s +%6.1fs %-5s] %s\n", os.date("%H:%M:%S"), tick() - t0, tostring(level), tostring(msg)))
    end
    K.LogPath = path
    local swPath = string.gsub(path, "%.log$", "_pcall.log")

    local state = { state = "running", path = path, started = os.time(), beat = os.time(), matches = 1, last = "",
        clock = os.clock(), tpAt = 0, peakMem = 0, maxStall = 0, stallAt = 0, kick = "", disc = "", crumbs = crumbs,
        swallowed = 0 }
    local function saveState()
        state.clock = os.clock()
        state.swallowed = K.Swallowed and K.Swallowed.total or 0
        if wrf then pcall(wrf, statePath, HttpService:JSONEncode(state)) end
    end

    local function guessCause(prev, gap)
        if prev.kick ~= nil and prev.kick ~= "" then
            return "Roblox showed an error prompt first (kick / anti-cheat / lost connection): " .. tostring(prev.kick)
        end
        if prev.disc ~= nil and prev.disc ~= "" then
            return "the connection to the server was closed first: " .. tostring(prev.disc)
        end
        if (tonumber(prev.peakMem) or 0) >= 3000 then
            return string.format("Roblox memory was very high (peak %.0f MB): most likely ran out of memory", tonumber(prev.peakMem))
        end
        if (tonumber(prev.maxStall) or 0) >= 3 then
            return string.format("the game froze for %.1f s shortly before the end (hang, then killed or crashed)", tonumber(prev.maxStall))
        end
        return "no warning of any kind (no kick prompt, no disconnect, no memory or freeze signs): the process was "
            .. "terminated from outside - anti-cheat termination, a client crash, or the window / task was closed"
    end

    local prev
    if rdf and isf then
        local ok, data = pcall(function()
            if isf(statePath) then return HttpService:JSONDecode(rdf(statePath)) end
            return nil
        end)
        if ok and type(data) == "table" then prev = data end
    end
    local prevNote = "none"
    if prev then
        local gap = os.time() - (tonumber(prev.beat) or 0)

        local sameProcess = tonumber(prev.clock) ~= nil and os.clock() >= tonumber(prev.clock) - 1
        if prev.state == "teleport" and gap < 300 and sameProcess then
            state.matches = (tonumber(prev.matches) or 1) + 1
            prevNote = string.format("server switch, %d s after the teleport started", os.time() - (tonumber(prev.tpAt) or os.time()))
        elseif prev.state == "clean" or prev.state == "left" then
            prevNote = "previous session ended normally (" .. tostring(prev.state) .. ")"
        elseif prev.path ~= path then
            prevNote = "PREVIOUS SESSION DID NOT END CLEANLY"
            local tail = ""
            pcall(function()
                if isf(prev.path) then
                    local rows = {}
                    for row in string.gmatch(rdf(prev.path), "[^\n]+") do rows[#rows + 1] = row end
                    tail = table.concat(rows, "\n", math.max(1, #rows - 14), #rows)
                end
            end)
            local lastActions = ""
            if type(prev.crumbs) == "table" then
                lastActions = "    " .. table.concat(prev.crumbs, "\n    ")
            end
            append(reportPath, string.format(
                "=== %s  a session ended without a clean exit (client crash, killed process, or the window was closed)\n"
                    .. "  likely cause     : %s\n"
                    .. "  state at the end : %s\n  session log      : %s\n  last sign of life: %s (%d s before this start)\n"
                    .. "  matches in chain : %s\n  last stats       : %s\n  peak memory      : %.0f MB | longest freeze in the last minute: %.1f s\n"
                    .. "  errors swallowed by pcall: %s (see the _pcall.log next to the session log)\n"
                    .. "  last actions before the end (newest last):\n%s\n  last log lines:\n%s\n\n",
                os.date("%Y-%m-%d %H:%M:%S"), guessCause(prev, gap), tostring(prev.state), tostring(prev.path),
                os.date("%H:%M:%S", tonumber(prev.beat) or 0), gap, tostring(prev.matches), tostring(prev.last),
                tonumber(prev.peakMem) or 0, tonumber(prev.maxStall) or 0, tostring(prev.swallowed), lastActions, tail))
            prevNote = "PREVIOUS SESSION DID NOT END CLEANLY - likely cause: " .. guessCause(prev, gap)
            warn("[XiaoYu Rebuild] the previous session did not end cleanly - see " .. reportPath)
        end
    end
    saveState()

    local executor = "?"
    pcall(function() executor = tostring((identifyexecutor or getexecutorname or function() return "?" end)()) end)
    local rbxVersion = "?"
    pcall(function() rbxVersion = version() end)
    K.Log("info", string.format("start build=%s account=%s place=%s job=%s private=%s match=%d executor=%s roblox=%s",
        tostring(K.Build), uid, tostring(game.PlaceId), tostring(game.JobId), tostring(game.PrivateServerId ~= ""),
        state.matches, executor, rbxVersion))
    K.Log("info", "previous: " .. prevNote .. (prev and prev.last ~= "" and (" | last stats: " .. tostring(prev.last)) or ""))
    warn("[XiaoYu Rebuild] diagnostics log: " .. path)

    if lsf and dlf then
        pcall(function()
            local mine = {}
            for _, f in ipairs(lsf(dir)) do
                local name = tostring(f)
                if string.find(name, "session_" .. uid .. "_", 1, true) then mine[#mine + 1] = name end
            end
            table.sort(mine)
            for i = 1, #mine - 80 do pcall(dlf, mine[i]) end
        end)
    end

    local conns = {}
    local function hook(signal, fn)
        local ok, c = pcall(function() return signal:Connect(fn) end)
        if ok and c then conns[#conns + 1] = c end
    end

    local statsLine
    hook(player.OnTeleport, function(st, placeId)

        K.Log("tp", string.format("%s place=%s | %s", tostring(st), tostring(placeId), statsLine and statsLine() or ""))
        if st == Enum.TeleportState.Started then
            state.state, state.beat, state.tpAt = "teleport", os.time(), os.time()
            saveState()
        elseif st == Enum.TeleportState.Failed then
            state.state, state.beat = "running", os.time()
            saveState()
        end
    end)
    hook(Players.PlayerRemoving, function(p)
        if p == player and state.state ~= "teleport" then
            K.Log("info", "local player is leaving")
            state.state, state.beat = "left", os.time()
            saveState()
        end
    end)
    pcall(function()
        game:BindToClose(function()
            if state.state ~= "teleport" then
                K.Log("info", "BindToClose")
                state.state, state.beat = "left", os.time()
                saveState()
            end
        end)
    end)

    local GuiService = game:GetService("GuiService")
    hook(GuiService.ErrorMessageChanged, function()
        local ok, msg = pcall(function() return GuiService:GetErrorMessage() end)
        if ok and msg and msg ~= "" then
            local okType, errType = pcall(function() return tostring(GuiService:GetErrorType()) end)
            K.Log("gui", "error prompt: " .. tostring(msg) .. (okType and (" (" .. errType .. ")") or ""))
            state.kick, state.beat = string.sub(tostring(msg), 1, 200), os.time()
            saveState()
        end
    end)

    pcall(function()
        hook(game:GetService("NetworkClient").ChildRemoved, function(child)
            K.Log("net", "NetworkClient child removed: " .. tostring(child))
            state.disc, state.beat = "NetworkClient child removed (" .. tostring(child) .. ")", os.time()
            saveState()
        end)
    end)
    pcall(function()
        local UIS = game:GetService("UserInputService")
        hook(UIS.WindowFocused, function() K.Crumb("window focused") end)
        hook(UIS.WindowFocusReleased, function() K.Crumb("window lost focus") end)
    end)
    local seen, logged = {}, 0
    local function noteError(kind, message)
        message = tostring(message)
        local key = string.sub(message, 1, 120)
        seen[key] = (seen[key] or 0) + 1
        if seen[key] <= 3 and logged < 300 then
            logged += 1
            K.Log(kind, string.sub(message, 1, 400))
        end
    end
    hook(game:GetService("LogService").MessageOut, function(message, messageType)
        if messageType == Enum.MessageType.MessageError then
            noteError("error", message)
        elseif messageType == Enum.MessageType.MessageWarning and string.find(message, "[XiaoYu", 1, true) then
            noteError("warn", message)
        end
    end)
    hook(game:GetService("ScriptContext").Error, function(message, trace)
        noteError("lua", tostring(message) .. " | " .. string.gsub(tostring(trace), "\n", " / "))
    end)

    local frames, elapsed, worstDt, stallLines = 0, 0, 0, 0
    hook(RunService.Heartbeat, function(dt)
        frames += 1
        elapsed += dt
        if dt > worstDt then worstDt = dt end

        if dt > 0.75 then
            if dt > state.maxStall then state.maxStall, state.stallAt = dt, os.time() end
            if stallLines < 100 then
                stallLines += 1
                K.Log("stall", string.format("frame took %.2f s | %s", dt, statsLine and statsLine() or ""))
            end
        end
    end)
    local Stats = game:GetService("Stats")
    function statsLine()
        local fps = elapsed > 0 and frames / elapsed or 0
        local mem, inst, ping = -1, -1, -1
        pcall(function() mem = Stats:GetTotalMemoryUsageMb() end)
        pcall(function() inst = Stats.InstanceCount end)
        pcall(function() ping = Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
        local luaMb = collectgarbage("count") / 1024
        if mem > state.peakMem then state.peakMem = mem end
        return string.format("fps=%.0f mem=%.0fMB lua=%.0fMB inst=%d ping=%.0fms worst-frame=%.2fs match=%d conns=%d pcall-errors=%d",
            fps, mem, luaMb, inst, ping, worstDt, state.matches, #K.connections, K.Swallowed and K.Swallowed.total or 0)
    end

    local function flushSwallowed(mode)
        local S = K.Swallowed
        if not S then return end
        if #S.new > 0 then
            local rows = {}
            for i, e in ipairs(S.new) do
                rows[#rows + 1] = string.format("[%s] %s  | pcall'd function defined at %s", os.date("%H:%M:%S"), e.msg, e.where)
                if i <= 3 then K.Crumb("pcall: " .. e.msg) end
            end
            S.new = {}
            if S.lines < 1500 then
                S.lines += #rows
                append(swPath, table.concat(rows, "\n") .. "\n")
            end
        end
        local function summary(limit)
            local list = {}
            for _, e in pairs(S.keys) do list[#list + 1] = e end
            table.sort(list, function(a, b) return a.n > b.n end)
            local out = {}
            for i = 1, math.min(limit, #list) do
                out[i] = string.format("  x%d  %s  | %s", list[i].n, list[i].msg, list[i].where)
            end
            return table.concat(out, "\n")
        end
        if mode == "final" then
            append(swPath, string.format("--- final: %d errors swallowed, %d distinct (%d more distinct ones not tracked). Most frequent:\n%s\n",
                S.total, S.nkeys, S.dropped, summary(25)))
        elseif mode == "summary" and S.total ~= S.lastSummaryTotal then
            S.lastSummaryTotal = S.total
            K.Log("pcall", string.format("swallowed so far: %d (%d distinct) | most frequent: %s", S.total, S.nkeys,
                string.gsub(summary(3), "\n", " ;")))
        end
    end

    task.spawn(function()
        local tick3 = 0
        while not K.destroyed do
            task.wait(3)
            tick3 += 1
            state.beat = os.time()
            if tick3 % 5 == 0 then
                state.last = statsLine()
                frames, elapsed, worstDt = 0, 0, 0
                K.Log("beat", state.last)
            end
            flushSwallowed(tick3 % 10 == 0 and "summary" or nil)
            if tick3 % 10 == 0 then
                state.maxStall = 0
            end
            saveState()
        end
    end)

    K.onUnload(function()
        flushSwallowed("final")
        for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
        K.Log("info", "unload (clean)")
        state.state, state.beat = "clean", os.time()
        saveState()
    end)
end

local Signal = {}
Signal.__index = Signal
function Signal.new() return setmetatable({ _handlers = {} }, Signal) end
function Signal:Connect(fn)
    local h = { fn = fn, connected = true }
    table.insert(self._handlers, h)
    local sig = self
    return {
        Connected = true,
        Disconnect = function(c)
            if not h.connected then return end
            h.connected = false
            c.Connected = false
            local i = table.find(sig._handlers, h)
            if i then table.remove(sig._handlers, i) end
        end,
    }
end
function Signal:Once(fn)
    local c
    c = self:Connect(function(...) c:Disconnect() fn(...) end)
    return c
end
function Signal:Fire(...)
    local list = table.clone(self._handlers)
    for _, h in ipairs(list) do
        if h.connected then task.spawn(h.fn, ...) end
    end
end
function Signal:FireSync(...)
    for _, h in ipairs(table.clone(self._handlers)) do
        if h.connected then h.fn(...) end
    end
end
function Signal:Destroy() table.clear(self._handlers) end
K.Signal = Signal

local Trove = {}
Trove.__index = Trove
function Trove.new(name) return setmetatable({ _name = name, _items = {} }, Trove) end
local function cleanItem(o)
    local t = typeof(o)
    if t == "RBXScriptConnection" then o:Disconnect()
    elseif t == "Instance" then pcall(function() o:Destroy() end)
    elseif t == "thread" then pcall(task.cancel, o)
    elseif type(o) == "function" then pcall(o)
    elseif type(o) == "table" then

        local function member(k)
            local ok, v = pcall(function() return o[k] end)
            return ok and type(v) == "function" and v or nil
        end
        local cancel, getStatus = member("cancel"), member("getStatus")
        if cancel and getStatus then pcall(cancel, o) return end
        local destroy = member("Destroy")
        if destroy then pcall(destroy, o) return end
        local disconnect = member("Disconnect")
        if disconnect then pcall(disconnect, o) end
    end
end
function Trove:Add(o) table.insert(self._items, o) return o end
function Trove:Connect(sig, fn) return self:Add(sig:Connect(fn)) end
function Trove:Extend() return self:Add(Trove.new(self._name)) end
function Trove:Remove(o, keep)
    local i = table.find(self._items, o)
    if i then
        table.remove(self._items, i)
        if not keep then cleanItem(o) end
    end
end

function Trove:AddPromise(promise)
    if tostring(promise:getStatus()) == "Started" then
        self:Add(promise)
        promise:finally(function()
            if not self._cleaning then self:Remove(promise, true) end
        end)
    end
    return promise
end

function Trove:AttachExtend(instance)
    local sub = self:Extend()
    sub:Connect(instance.Destroying, function() self:Remove(sub) end)
    return sub
end
function Trove:Clean()
    local items = self._items
    self._items = {}
    self._cleaning = true
    for i = #items, 1, -1 do cleanItem(items[i]) end
    self._cleaning = false
end
Trove.Destroy = Trove.Clean
K.Trove = Trove

