do
    local XYPlayers = game:GetService("Players")
    local XYRunService = game:GetService("RunService")
    local XYWorkspace = game:GetService("Workspace")
    local XYSoundService = game:GetService("SoundService")
    local XYHttp = game:GetService("HttpService")
    local XYLocalPlayer = XYPlayers.LocalPlayer

    K.XY = {
        void = { on = false, dist = 1, sx = 10000000, sy = 0, sz = 10000000, method = "Static", pattern = "None", speed = 10, radius = 10000, wtype = "Projectile" },
        riot = { on = false, behind = 10, height = 0, rate = 0.5 },
        aa = { on = false, pitch = "None", rotate = 45, type = "None", speed = 1500 },
        tp = { on = false },
        k8x = { on = false },
        ctr = { on = false, mode = "ue counter", legits = true, bots = true, maxlegits = 1, delay = 3,
                stay = 0.35, gap = 0.5, lead = 6, voidspeed = 3000,
                cycle = 50, fly = 25, boost = 100000, boostms = 600, flyspeed = 15000,
                zigamp = 400, zigfreq = 8, depth = 6, radius = 30 },
        snd = { name = "Keyboard", vol = 1 },
    }
    K.XYLabels = {}
    K.XYRageActive = function() return false end

    local S = K.XY
    local XYConns = {}
    local XYElapsed = 0
    local XYVoidPos0 = nil
    local XYFloorY = 0
    local XYTpTarget, XYTpCurrent = nil, nil
    local XYK8 = { lastPos = nil, fakeY = -21827262828, current = 2147483647, flip = true }
    local XYCtrState = { started = false, mode = nil, startPos = nil, lastArm = 0 }
    local XYUE = { legit = { last = 0, inPos = false }, bot = { last = 0, inPos = false }, voidState = 2, voidT = 0, lastRandTp = 0 }
    local XYK = { t0 = 0, boostAt = 0, fly = Vector3.new(), stop = nil, stopIdx = -1, spawn = nil, list = {}, last = -1 }
    local XYCounterModeDisplay = { ["ue counter"] = "UE 計數器", ["Kicia counter"] = "循環計數器", ["Solix counter"] = "Solix 計數器" }

    local function xyc(labelKey, text)
        local f = K.XYLabels[labelKey]
        if f then pcall(f, text) end
    end

    local function XYRoot()
        local c = XYLocalPlayer.Character
        return c and c:FindFirstChild("HumanoidRootPart") or nil
    end
    local function XYHum()
        local c = XYLocalPlayer.Character
        return c and c:FindFirstChildOfClass("Humanoid") or nil
    end

    K.onUnload(function()
        for _, c in pairs(XYConns) do pcall(function() c:Disconnect() end) end
        XYConns = {}
        pcall(XYStopVoidSound)
        S.void.on, S.riot.on, S.aa.on, S.tp.on, S.k8x.on, S.ctr.on = false, false, false, false, false, false
        local hum = XYHum()
        if hum then pcall(function() hum.WalkSpeed = 16 hum.JumpPower = 50 hum.JumpHeight = 7.2 end) end
    end)

    local XYKEYBOARD_B64 = [[]]
    local XYSPACE_B64 = [[]]
    local XYDISABLE_B64 = [[]]

    local function XYB64(data)
        local ok, out = pcall(function()
            local c = K.fn("crypt")
            if c and c.base64decode then return c.base64decode(data) end
            return nil
        end)
        if ok and out then return out end
        local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        data = data:gsub("[^" .. b .. "=]", "")
        return (data:gsub(".", function(x)
            if x == "=" then return "" end
            local r, f = "", (b:find(x) - 1)
            for i = 6, 1, -1 do
                r = r .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
            end
            return r
        end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(x)
            if #x ~= 8 then return "" end
            local c = 0
            for i = 1, 8 do
                c = c + (x:sub(i, i) == "1" and 2 ^ (8 - i) or 0)
            end
            return string.char(c)
        end))
    end

    local function XYEnsureAsset(path, b64)
        local wrf, isf, mkf = K.fn("writefile"), K.fn("isfile"), K.fn("makefolder")
        if not wrf then return nil end
        pcall(function() if mkf and not isfolder("XiaoYu") then makefolder("XiaoYu") end end)
        local have = false
        if isf then
            local okf, hv = pcall(isf, path)
            have = okf and hv == true
        end
        if not have then
            local data = XYB64(b64)
            if data then pcall(wrf, path, data) end
        end
        local gca = K.fn("getcustomasset") or K.fn("getsynasset")
        if gca and isf then
            local ok, asset = pcall(gca, path)
            if ok and asset then return asset end
        end
        return nil
    end

    local XYActiveSounds = {}
    K.XYActiveSounds = XYActiveSounds
    local XYSoundLoopConn = nil
    local XYSoundKeepAlive = false
    local XYSoundGen = 0
    local XYKeyboardAsset, XYSpaceAsset, XYDisableAsset = nil, nil, nil

    local XYSoundIds = {
        None = nil,
        Keyboard = "custom:keyboard",
        Space = "custom:space",
        Whoosh = "rbxasset://sounds/impact_water.mp3",
        Glitch = "rbxasset://sounds/electronicpingshort.wav",
        Ambient = "rbxasset://sounds/background_music_loop.mp3",
        Bass = "rbxasset://sounds/swoosh.wav",
        Pulse = "rbxasset://sounds/switch.wav",
        Static = "rbxasset://sounds/collision.wav",
        Distortion = "rbxasset://sounds/action_footsteps_plastic.mp3",
        Rocket = "rbxassetid://12222216",
        Laser = "rbxassetid://137147059",
        Drone = "rbxasset://sounds/action_falling.mp3",
        Rush = "rbxasset://sounds/impact_water.mp3",
        Hum = "rbxasset://sounds/swoosh.wav",
    }

    local function XYSoundFolder()
        local pg = XYLocalPlayer:FindFirstChild("PlayerGui")
        if pg then
            local folder = pg:FindFirstChild("XiaoYuSounds")
            if not folder then
                folder = Instance.new("Folder")
                folder.Name = "XiaoYuSounds"
                folder.Parent = pg
            end
            return folder
        end
        return XYSoundService
    end

    local function XYWipeSounds()
        for _, s in ipairs(XYActiveSounds) do
            pcall(function()
                s.Looped = false
                s.Volume = 0
                s:Stop()
                s.SoundId = ""
                s:Destroy()
            end)
        end
        table.clear(XYActiveSounds)
        local function kill(child)
            pcall(function()
                child.Looped = false
                child.Volume = 0
                child:Stop()
                child.SoundId = ""
                child:Destroy()
            end)
        end
        local function sweep(container)
            if not container then return end
            for _, ch in ipairs(container:GetDescendants()) do
                if ch:IsA("Sound") and (ch.Name == "XiaoYuSFX" or ch.Name == "XiaoYuDisable") then kill(ch) end
            end
        end
        sweep(XYSoundService)
        sweep(XYLocalPlayer:FindFirstChild("PlayerGui"))
        sweep(XYLocalPlayer.Character)
    end

    local function XYClearSounds()
        XYSoundKeepAlive = false
        XYSoundGen = XYSoundGen + 1
        if XYSoundLoopConn then
            pcall(function() XYSoundLoopConn:Disconnect() end)
            XYSoundLoopConn = nil
        end
        XYWipeSounds()
        task.defer(XYWipeSounds)
        task.delay(0.1, XYWipeSounds)
    end

    local function XYResolveSound(name)
        local id = XYSoundIds[name]
        if id == "custom:keyboard" then
            if not XYKeyboardAsset then XYKeyboardAsset = XYEnsureAsset("XiaoYu/keyboard.mp3", XYKEYBOARD_B64) end
            return XYKeyboardAsset
        elseif id == "custom:space" then
            if not XYSpaceAsset then XYSpaceAsset = XYEnsureAsset("XiaoYu/space.mp3", XYSPACE_B64) end
            return XYSpaceAsset
        end
        return id
    end

    local function XYSpawnLayer(id, speed, volMul, gen)
        local s = Instance.new("Sound")
        s.Name = "XiaoYuSFX"
        s.SoundId = id
        s.Volume = math.clamp(S.snd.vol * (volMul or 1), 0, 10)
        s.Looped = true
        s.PlaybackSpeed = speed or 1
        s.Parent = XYSoundFolder()
        s.Ended:Connect(function()
            if not XYSoundKeepAlive or gen ~= XYSoundGen then return end
            pcall(function() s.TimePosition = 0 s:Play() end)
        end)
        pcall(function() s:Play() end)
        pcall(function() XYSoundService:PlayLocalSound(s) end)
        task.spawn(function()
            for _ = 1, 20 do
                if not XYSoundKeepAlive or gen ~= XYSoundGen then return end
                if s.IsPlaying then return end
                pcall(function() s:Play() XYSoundService:PlayLocalSound(s) end)
                task.wait(0.1)
            end
        end)
        table.insert(XYActiveSounds, s)
    end

    function XYStartVoidSound()
        XYClearSounds()
        local name = S.snd.name
        if not name or name == "None" then return end
        local id = XYResolveSound(name)
        if not id then return end
        XYSoundKeepAlive = true
        local gen = XYSoundGen
        if name == "Keyboard" or name == "Space" then
            XYSpawnLayer(id, 1.0, 1.0, gen)
        elseif name == "Drone" or name == "Ambient" then
            XYSpawnLayer(id, 0.55, 1.2, gen)
            XYSpawnLayer(id, 0.85, 0.7, gen)
            XYSpawnLayer(id, 1.15, 0.4, gen)
        elseif name == "Bass" or name == "Hum" then
            XYSpawnLayer(id, 0.4, 1.4, gen)
            XYSpawnLayer(id, 0.65, 0.9, gen)
        elseif name == "Whoosh" or name == "Rush" then
            XYSpawnLayer(id, 0.7, 1.1, gen)
            XYSpawnLayer(id, 1.0, 0.8, gen)
        elseif name == "Glitch" or name == "Static" or name == "Pulse" then
            XYSpawnLayer(id, 0.9, 1.0, gen)
            XYSpawnLayer(id, 1.2, 0.6, gen)
        else
            XYSpawnLayer(id, 1.0, 1.0, gen)
        end
        XYSoundLoopConn = XYRunService.Heartbeat:Connect(function()
            if not XYSoundKeepAlive or gen ~= XYSoundGen or not S.void.on then return end
            for _, s in ipairs(XYActiveSounds) do
                if s and s.Parent and not s.IsPlaying then
                    pcall(function() s.TimePosition = 0 s:Play() end)
                end
            end
        end)
    end

    function XYStopVoidSound()
        XYClearSounds()
    end

    function XYPlayDisableSound()
        task.spawn(function()
            if not XYDisableAsset then XYDisableAsset = XYEnsureAsset("XiaoYu/void_disable.mp3", XYDISABLE_B64) end
            if not XYDisableAsset then return end
            local s = Instance.new("Sound")
            s.Name = "XiaoYuDisable"
            s.SoundId = XYDisableAsset
            s.Volume = math.clamp(S.snd.vol, 0, 10)
            s.Parent = XYSoundFolder()
            pcall(function() s:Play() end)
            task.delay(6, function() pcall(function() if s and s.Parent then s:Destroy() end end) end)
        end)
    end

    local XYTestToken = 0
    function XYTestSound()
        XYStopVoidSound()
        XYTestToken = XYTestToken + 1
        local myToken = XYTestToken
        if S.snd.name == "None" then return end
        XYStartVoidSound()
        task.delay(3, function()
            if myToken ~= XYTestToken then return end
            XYStopVoidSound()
            if S.void.on and S.snd.name ~= "None" then XYStartVoidSound() end
        end)
    end

    local function XYVoidRanges()
        local pct = math.clamp(S.void.dist, 0, 1)
        return math.clamp(math.abs(S.void.sx) * pct, 0, 10000000),
               math.clamp(math.abs(S.void.sy) * pct, 0, 10000000),
               math.clamp(math.abs(S.void.sz) * pct, 0, 10000000)
    end

    local function XYVoidOffset()
        local xMax, yMax, zMax = XYVoidRanges()
        local ox, oy, oz = 0, 0, 0
        local m = S.void.method
        if m == "Fixed" then
            ox = S.void.sx * S.void.dist
            oy = S.void.sy * S.void.dist
            oz = S.void.sz * S.void.dist
        elseif m == "Endpoints" then
            ox = (math.random(0, 1) == 1 and 1 or -1) * xMax
            oy = (yMax > 0) and ((math.random(0, 1) == 1 and 1 or -1) * yMax) or 0
            oz = (math.random(0, 1) == 1 and 1 or -1) * zMax
        elseif m == "Static" or m == "Random" or m == "Chaos" then
            ox = (math.random() * 2 - 1) * xMax
            oy = (math.random() * 2 - 1) * yMax
            oz = (math.random() * 2 - 1) * zMax
        elseif m == "Quantum" then
            local sg = math.random(0, 1) == 1 and 1 or -1
            ox = sg * xMax * (0.7 + math.random() * 0.3)
            oy = (math.random() * 2 - 1) * yMax
            oz = sg * zMax * (0.7 + math.random() * 0.3)
        elseif m == "Drift" then
            local t = XYElapsed
            ox = math.noise(t * 0.2, 1.1) * 2 * xMax
            oy = math.noise(2.2, t * 0.15) * 2 * yMax
            oz = math.noise(t * 0.18, t * 0.12) * 2 * zMax
        elseif m == "Loop" then
            local r = math.max(xMax, zMax)
            ox = math.cos(XYElapsed * 3) * r
            oy = math.sin(XYElapsed * 1.5) * yMax
            oz = math.sin(XYElapsed * 3) * r
        elseif m == "Spiral" then
            local r = math.max(xMax, zMax) * (0.25 + 0.75 * math.abs(math.sin(XYElapsed * 0.5)))
            ox = math.cos(XYElapsed * 4) * r
            oy = math.sin(XYElapsed * 0.8) * yMax
            oz = math.sin(XYElapsed * 4) * r
        else
            ox = (math.random() * 2 - 1) * xMax
            oy = (math.random() * 2 - 1) * yMax
            oz = (math.random() * 2 - 1) * zMax
        end
        local base = XYVoidPos0 or Vector3.new()
        return Vector3.new(base.X + ox, base.Y + oy, base.Z + oz)
    end

    local function XYApplyMotion(pos)
        local pattern = S.void.pattern
        if pattern == "None" then return pos end
        local spd = math.max(S.void.speed, 1)
        local rad = math.clamp(S.void.radius, 0, 214748364)
        if pattern == "Spin" then
            local a = XYElapsed * (spd * 0.08)
            local r = math.min(rad, 100000)
            return pos + Vector3.new(math.cos(a) * r, 0, math.sin(a) * r)
        elseif pattern == "Orbit" then
            local a = XYElapsed * (spd * 0.05)
            local r = math.min(rad, 200000)
            return pos + Vector3.new(math.cos(a) * r, math.sin(a * 0.4) * r * 0.2, math.sin(a) * r)
        elseif pattern == "Random" then
            local r = math.min(rad, 300000)
            return pos + Vector3.new((math.random() - 0.5) * r, (math.random() - 0.5) * r * 0.4, (math.random() - 0.5) * r)
        elseif pattern == "Desync" then
            local a = XYElapsed * (spd * 0.12)
            local r = math.min(rad, 250000)
            return pos + Vector3.new(math.sin(a) * r, math.cos(a * 1.4) * r * 0.35, math.sin(a * 0.6) * r)
        elseif pattern == "Erratic" then
            local r = math.min(rad * 1.5, 500000)
            return pos + Vector3.new((math.random() - 0.5) * r, (math.random() - 0.5) * r * 0.5, (math.random() - 0.5) * r)
        end
        return pos
    end

    function XYVoidSet(on)
        S.void.on = on
        if on then
            local hrp = XYRoot()
            if hrp then XYVoidPos0 = hrp.Position end
            XYElapsed = 0
            XYStartVoidSound()
        else
            XYStopVoidSound()
            local hrp = XYRoot()
            if hrp and XYVoidPos0 then
                hrp.CFrame = CFrame.new(XYVoidPos0)
                hrp.AssemblyLinearVelocity = Vector3.new()
                hrp.AssemblyAngularVelocity = Vector3.new()
            end
            XYVoidPos0 = nil
            task.delay(0.35, function() XYPlayDisableSound() end)
        end
    end

    local XYRiotTarget, XYRiotLast = nil, 0
    local function XYClosestEnemy()
        local hrp = XYRoot()
        if not hrp then return nil end
        local best, bestDist = nil, math.huge
        for _, p in ipairs(XYPlayers:GetPlayers()) do
            if p ~= XYLocalPlayer and p.Character then
                local thrp = p.Character:FindFirstChild("HumanoidRootPart")
                local thum = p.Character:FindFirstChildOfClass("Humanoid")
                if thrp and thum and thum.Health > 0 then
                    local d = (hrp.Position - thrp.Position).Magnitude
                    if d < bestDist then bestDist = d best = p end
                end
            end
        end
        return best
    end

    function XYRiotSet(on)
        S.riot.on = on
        if not on then
            XYRiotTarget = nil
            local hum = XYHum()
            if hum then
                pcall(function() hum.WalkSpeed = 16 hum.JumpPower = 50 hum.JumpHeight = 7.2 end)
            end
        end
    end

    local XYAaAngle, XYAaDir = 0, 1
    local function XYAaStep(dt)
        local hrp = XYRoot()
        if not hrp then return end
        local pitch = 0
        local p = S.aa.pitch
        if p == "Up" then
            pitch = math.rad(-89)
        elseif p == "Down" then
            pitch = math.rad(89)
        elseif p == "Flip" then
            pitch = math.rad((math.random() > 0.5) and -89 or 89)
        end
        local yaw = 0
        local typ, spd, rot = S.aa.type, S.aa.speed, S.aa.rotate
        if typ == "Spin" then
            XYAaAngle = (XYAaAngle + spd * dt * 0.1) % 360
            yaw = math.rad(XYAaAngle)
        elseif typ == "Jitter" then
            yaw = math.rad((math.random() > 0.5 and 1 or -1) * rot)
        elseif typ == "Pixelated" then
            local steps = math.max(math.floor(360 / math.max(rot, 1)), 1)
            XYAaAngle = (XYAaAngle + spd * dt * 0.05) % steps
            yaw = math.rad(XYAaAngle * (360 / steps))
        elseif typ == "Sway" then
            XYAaAngle = XYAaAngle + spd * dt * 0.05 * XYAaDir
            if XYAaAngle >= rot then
                XYAaAngle = rot
                XYAaDir = -1
            elseif XYAaAngle <= -rot then
                XYAaAngle = -rot
                XYAaDir = 1
            end
            yaw = math.rad(XYAaAngle)
        elseif typ == "Inverter" then
            XYAaAngle = (XYAaAngle + spd * dt * 0.08)
            if XYAaAngle % 2 < 1 then yaw = math.rad(rot) else yaw = math.rad(rot + 180) end
        end
        local pos = hrp.Position
        hrp.CFrame = CFrame.new(pos) * CFrame.Angles(pitch, yaw, 0)
    end

    function XYTpSet(on)
        S.tp.on = on
        if not on then XYTpCurrent = nil end
    end

    function XYK8xSet(on)
        S.k8x.on = on
        if on then
            local hrp = XYRoot()
            if hrp then XYK.lastPos = hrp.CFrame end
            XYK.fakeY = -21827262828
            XYK.current = 2147483647
        else
            local hrp = XYRoot()
            if hrp and XYK.lastPos then
                hrp.CFrame = XYK.lastPos
                hrp.AssemblyLinearVelocity = Vector3.new()
            end
        end
    end

    local function XYCycleTimes()
        local cycle = math.max(S.ctr.cycle, 5) / 1000
        local flyWindow = math.min(S.ctr.fly / 1000, cycle * 0.95)
        return cycle, flyWindow
    end

    local function XYBlockerParams()
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local list = {}
        if XYLocalPlayer.Character then table.insert(list, XYLocalPlayer.Character) end
        params.FilterDescendantsInstances = list
        return params
    end

    local function XYBuildSpawnList(spawn)
        XYK.spawn = spawn
        XYK.list = {}
        local params = XYBlockerParams()
        local depth = S.ctr.depth
        local radius = S.ctr.radius
        local rng = Random.new()
        for _ = 1, 60 do
            if #XYK.list >= 16 then break end
            local angle = rng:NextNumber(0, math.pi * 2)
            local dist = rng:NextNumber(4, math.max(radius, 5))
            local origin = spawn + Vector3.new(math.cos(angle) * dist, 8, math.sin(angle) * dist)
            local ok, hit = pcall(function()
                return XYWorkspace:Raycast(origin, Vector3.new(0, -30, 0), params)
            end)
            if ok and hit and hit.Normal.Y > 0.7 then
                XYK.list[#XYK.list + 1] = hit.Position - Vector3.new(0, depth, 0)
            end
        end
    end

    local function XYResolveStop(mode, spawn)
        local fallback = spawn - Vector3.new(0, S.ctr.depth, 0)
        if mode ~= "Solix counter" then return fallback end
        if XYK.spawn ~= spawn then XYBuildSpawnList(spawn) end
        local n = #XYK.list
        if n == 0 then return fallback end
        local idx = math.random(1, n)
        if n > 1 and idx == XYK.last then idx = idx % n + 1 end
        XYK.last = idx
        return XYK.list[idx]
    end

    local function XYCycleStep(mode, root, dt)
        local now = os.clock()
        local t = now - XYK.t0
        local cycle, flyWindow = XYCycleTimes()
        local flying = (t % cycle) < flyWindow
        if now >= XYK.boostAt then
            if flying then
                XYK.fly = XYK.fly + Vector3.new(0, S.ctr.boost, 0)
            end
            XYK.boostAt = now + S.ctr.boostms / 1000
        end
        if not flying then
            local idx = math.floor(t / cycle)
            if idx ~= XYK.stopIdx or not XYK.stop then
                XYK.stopIdx = idx
                XYK.stop = XYResolveStop(mode, XYK.spawn)
            end
            root.CFrame = CFrame.new(XYK.stop) * CFrame.Angles(math.pi / 2, 0, 0)
        else
            local zig = math.cos(t * S.ctr.zigfreq) * S.ctr.zigamp * dt
            XYK.fly = XYK.fly + Vector3.new(zig, S.ctr.flyspeed * dt, 0)
            root.CFrame = CFrame.new(XYK.fly) * CFrame.Angles(-math.pi / 2, 0, 0)
        end
        root.AssemblyLinearVelocity = Vector3.new()
    end

    local function XYSendToVoid(root)
        root.CFrame = CFrame.new(10000000, 0, 10000000) * CFrame.Angles(-math.pi / 2, 0, 0)
        root.AssemblyLinearVelocity = Vector3.new()
    end

    local function XYUnderMap(pos)
        return pos.Y < (XYFloorY - 120)
    end

    local function XYOtherAlive()
        local list = {}
        for _, p in ipairs(XYPlayers:GetPlayers()) do
            if p ~= XYLocalPlayer and p.Character then
                local h = p.Character:FindFirstChildOfClass("Humanoid")
                local r = p.Character:FindFirstChild("HumanoidRootPart")
                if h and r and h.Health > 0 then table.insert(list, p) end
            end
        end
        return list
    end

    local function XYFindLegit()
        local list = XYOtherAlive()
        local hrp = XYRoot()
        if #list == 0 or not hrp then return nil, 0 end
        local best, bestDist = nil, math.huge
        for _, p in ipairs(list) do
            local d = (hrp.Position - p.Character.HumanoidRootPart.Position).Magnitude
            if d < bestDist then bestDist = d best = p end
        end
        return best, #list
    end

    local function XYUeStep(now, target, isLegit, setStatus)
        local char = XYLocalPlayer.Character
        local root = XYRoot()
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not (root and hum) then return end
        pcall(function()
            hum.PlatformStand = true
            hum.WalkSpeed = 0
        end)
        if target and target.Character then
            local tRoot = target.Character:FindFirstChild("HumanoidRootPart")
            if tRoot then
                local stay = S.ctr.stay
                local gap = S.ctr.gap
                local lead = S.ctr.lead
                local slot = isLegit and XYUE.legit or XYUE.bot
                if not slot.inPos then
                    if now - slot.last >= gap then slot.inPos = true slot.last = now end
                elseif now - slot.last >= stay then
                    pcall(XYSendToVoid, root)
                    slot.inPos = false
                    slot.last = now
                end
                if slot.inPos then
                    local pos = tRoot.Position
                    local vel = tRoot.AssemblyLinearVelocity
                    if vel.Magnitude > 0.5 then pos = pos + vel.Unit * lead end
                    if XYUnderMap(pos) then
                        pcall(XYSendToVoid, root)
                        setStatus("目標進入地圖下方")
                        return
                    end
                    pcall(function()
                        root.CFrame = CFrame.new(pos + Vector3.new(0, 0, 1), pos + tRoot.CFrame.LookVector) * CFrame.Angles(-math.pi / 2, 0, 0)
                        root.AssemblyLinearVelocity = Vector3.new()
                    end)
                    setStatus(("正在 %s 上"):format(target.Name:sub(1, 14)))
                    return
                end
                pcall(XYSendToVoid, root)
                setStatus(("等待 %s"):format(target.Name:sub(1, 14)))
                return
            end
        end
        local elapsed = now - XYUE.voidT
        if XYUE.voidState == 1 then
            if elapsed >= 15 then
                XYUE.voidState = 2
                XYUE.voidT = now
            else
                pcall(function()
                    root.AssemblyLinearVelocity = Vector3.new(0, S.ctr.voidspeed, 0)
                end)
                if now - XYUE.lastRandTp >= 10 then
                    XYUE.lastRandTp = now
                    pcall(function()
                        root.CFrame = CFrame.new(root.Position + Vector3.new(
                            math.random(-2500, 2500), math.random(500, 1200), math.random(-2500, 2500)
                        )) * CFrame.Angles(-math.pi / 2, 0, 0)
                    end)
                end
            end
        else
            local y = root.Position.Y
            local floorY = XYFloorY - 1000
            pcall(function()
                root.CFrame = CFrame.new(root.Position.X, y - (y - floorY) * 0.5, root.Position.Z) * CFrame.Angles(-math.pi / 2, 0, 0)
            end)
            XYUE.voidState = 1
            XYUE.voidT = now
            XYUE.lastRandTp = now
        end
        setStatus("在虛空中")
    end

    local function XYCounterStop()
        XYCtrState.started = false
        XYCtrState.mode = nil
        XYUE.voidState = 2
        XYUE.voidT = 0
        XYUE.legit.last = 0
        XYUE.legit.inPos = false
        XYUE.bot.last = 0
        XYUE.bot.inPos = false
        local char = XYLocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then pcall(function() hum.PlatformStand = false hum.WalkSpeed = 16 end) end
        if XYCtrState.startPos then
            local root = XYRoot()
            if root then
                root.CFrame = CFrame.new(XYCtrState.startPos)
                root.AssemblyLinearVelocity = Vector3.new()
            end
        end
    end

    local function XYCounterTick(now, dt)
        local on = S.ctr.on
        local rageOn = false
        pcall(function() rageOn = K.XYRageActive() and true or false end)
        local busy = S.void.on or S.riot.on or S.k8x.on or S.tp.on
        if on and (rageOn or busy) then
            if XYCtrState.started then XYCounterStop() end
            xyc("ctr", rageOn and "計數器｜已暫停（狂暴機器人開啟中）" or "計數器｜已暫停（與其他傳送功能衝突）")
            return
        end
        if not on then
            if XYCtrState.started then XYCounterStop() end
            xyc("ctr", "計數器｜關閉")
            return
        end
        local mode = S.ctr.mode
        if XYCtrState.started and XYCtrState.mode and mode ~= XYCtrState.mode then
            xyc("ctr", "計數器｜請先關閉再開啟以切換模式")
            mode = XYCtrState.mode
        end
        local root = XYRoot()
        if not root then
            xyc("ctr", "計數器｜沒有角色")
            return
        end
        if not XYCtrState.started then
            XYCtrState.started = true
            XYCtrState.mode = mode
            XYCtrState.startPos = root.Position
            XYFloorY = root.Position.Y
            XYUE.voidState = 2
            XYUE.voidT = now
            XYUE.legit.last = 0
            XYUE.bot.last = 0
            XYK.t0 = now
            XYK.boostAt = now
            XYK.spawn = root.Position
            XYK.fly = root.Position
            XYK.stop = nil
            XYK.stopIdx = -1
            XYK.last = -1
            XYCtrState.lastArm = now
        end
        local status = ""
        if mode == "Kicia counter" or mode == "Solix counter" then
            pcall(XYCycleStep, mode, root, dt)
            status = (mode == "Kicia counter") and "循環中" or "Solix 循環中"
        else
            local delay = S.ctr.delay
            local armed = delay <= 0 or (now - XYCtrState.lastArm >= delay)
            local target, isLegit = nil, false
            if S.ctr.legits and armed then
                local legit, legitCount = XYFindLegit()
                if legit then
                    target = legit
                    isLegit = true
                elseif legitCount > math.floor(S.ctr.maxlegits) then
                    status = ("%d 個真實玩家，超過上限"):format(legitCount)
                end
            end
            if not armed and status == "" then
                status = ("真實玩家 %.1f 秒後就緒"):format(math.max(delay - (now - XYCtrState.lastArm), 0))
            end
            if #XYOtherAlive() == 0 then status = "伺服器沒有其他玩家" end
            XYUeStep(now, target, isLegit, function(s) status = s end)
        end
        xyc("ctr", ("計數器｜%s - %s"):format(XYCounterModeDisplay[XYCtrState.mode] or "?", status))
    end

    if not K.XYEngineStarted then
        K.XYEngineStarted = true
        XYConns.heartbeat = XYRunService.Heartbeat:Connect(function(dt)
            if K.destroyed then return end
            XYElapsed = XYElapsed + dt
            local hrp = XYRoot()

            if S.void.on and hrp then
                if not XYVoidPos0 then XYVoidPos0 = hrp.Position end
                local target = XYApplyMotion(XYVoidOffset())
                hrp.CFrame = CFrame.new(target)
                hrp.AssemblyLinearVelocity = Vector3.new()
                hrp.AssemblyAngularVelocity = Vector3.new()
                return
            end

            if S.riot.on and hrp then
                local now = os.clock()
                if (now - XYRiotLast) >= S.riot.rate or not XYRiotTarget or not XYRiotTarget.Parent then
                    XYRiotTarget = XYClosestEnemy()
                    XYRiotLast = now
                end
                if XYRiotTarget and XYRiotTarget.Character then
                    local thrp = XYRiotTarget.Character:FindFirstChild("HumanoidRootPart")
                    local thum = XYRiotTarget.Character:FindFirstChildOfClass("Humanoid")
                    if thrp and thum and thum.Health > 0 then
                        local look = thrp.CFrame.LookVector
                        local behind = Vector3.new(-look.X, 0, -look.Z)
                        if behind.Magnitude < 0.05 then
                            behind = Vector3.new(0, 0, -1)
                        else
                            behind = behind.Unit
                        end
                        local targetPos = thrp.Position + behind * S.riot.behind + Vector3.new(0, S.riot.height, 0)
                        hrp.CFrame = CFrame.new(targetPos, thrp.Position)
                        hrp.AssemblyLinearVelocity = Vector3.new()
                        hrp.AssemblyAngularVelocity = Vector3.new()
                        local hum = XYHum()
                        if hum then
                            pcall(function() hum.WalkSpeed = 0 hum.JumpPower = 0 hum.JumpHeight = 0 end)
                        end
                        return
                    else
                        XYRiotTarget = nil
                    end
                end
            end

            if S.aa.on and hrp and not S.riot.on then
                XYAaStep(dt)
            end
        end)

        task.spawn(function()
            while not K.destroyed do
                if S.tp.on then
                    local plrs = {}
                    for _, p in ipairs(XYPlayers:GetPlayers()) do
                        if p ~= XYLocalPlayer then table.insert(plrs, p) end
                    end
                    for _, plr in ipairs(plrs) do
                        if not S.tp.on or K.destroyed then break end
                        if plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
                            XYTpCurrent = plr
                            local myRoot = XYRoot()
                            local targetRoot = plr.Character:FindFirstChild("HumanoidRootPart")
                            if myRoot and targetRoot and not S.void.on and not S.riot.on and not S.k8x.on then
                                pcall(function()
                                    myRoot.CFrame = targetRoot.CFrame * CFrame.new(0, 0, 3)
                                    myRoot.AssemblyLinearVelocity = Vector3.new()
                                end)
                            end
                            task.wait(1.5)
                        end
                    end
                end
                task.wait(0.5)
            end
        end)

        task.spawn(function()
            while not K.destroyed do
                if S.k8x.on and not S.void.on and not S.riot.on and not S.ctr.on then
                    XYK.fakeY = XYK.fakeY + math.random(1000, 3000)
                    XYK.current = XYK.current + (XYK.fakeY - XYK.current) * 0.1
                    xyc("k8y", ("Y: %d"):format(math.floor(XYK.current)))
                    pcall(function()
                        local hrp = XYRoot()
                        if hrp then
                            local mn, mx = 10000000000, 100000000000
                            local rx = math.random(mn, mx)
                            local ry = math.random(mn, mx)
                            local rz = math.random(mn, mx)
                            if not XYK.flip then
                                rx, ry, rz = -rx, -ry, -rz
                            end
                            XYK.flip = not XYK.flip
                            hrp.CFrame = CFrame.new(rx, ry, rz)
                            hrp.AssemblyLinearVelocity = Vector3.new()
                        end
                    end)
                else
                    pcall(function()
                        local hrp = XYRoot()
                        if hrp then xyc("k8y", ("Y: %d"):format(math.floor(hrp.Position.Y))) end
                    end)
                end
                task.wait(0.12)
            end
        end)

        local XYLastCtr = os.clock()
        task.spawn(function()
            while not K.destroyed do
                local now = os.clock()
                local dt = now - XYLastCtr
                XYLastCtr = now
                pcall(XYCounterTick, now, dt)
                task.wait(0.05)
            end
        end)
    end
end

