local XYBG_URL = "https://i.postimg.cc/x15yQX00/file-00000000c3ec81f8bae6b914ced68223.png"
K.XYApplyMenuBackground = function(menu)
    return pcall(function()
        local chrome = rawget(menu, "_chrome")
        local window = chrome and chrome.Window
        local frame = window and window.MenuFrame
        if not frame or frame:FindFirstChild("XiaoYuBg") then return end
        local asset = nil
        local wrf, isf = K.fn("writefile"), K.fn("isfile")
        local mkf, isfd = K.fn("makefolder"), K.fn("isfolder")
        local gca = K.fn("getcustomasset") or K.fn("getsynasset")
        if wrf and gca then
            local have = false
            if isf then
                local okf, hv = pcall(isf, "XiaoYu/bg.png")
                have = okf and hv == true
            end
            if not have then
                local okd, data = pcall(function() return game:HttpGet(XYBG_URL) end)
                if okd and type(data) == "string" and #data > 1000 then
                    pcall(function()
                        if mkf and isfd and not isfd("XiaoYu") then mkf("XiaoYu") end
                    end)
                    pcall(wrf, "XiaoYu/bg.png", data)
                end
            end
            local oka, a = pcall(gca, "XiaoYu/bg.png")
            if oka and a then asset = a end
        end
        if not asset then return end
        local img = Instance.new("ImageLabel")
        img.Name = "XiaoYuBg"
        img.Image = asset
        img.BackgroundTransparency = 1
        img.AnchorPoint = Vector2.new(0.5, 0.5)
        img.Position = UDim2.fromScale(0.5, 0.5)
        img.Size = UDim2.fromScale(1, 1)
        img.ScaleType = Enum.ScaleType.Crop
        img.ImageTransparency = 0.1
        img.ZIndex = -5
        img.Parent = frame
    end)
end

