    local Group = {}
    Group.__index = Group
    setmetatable(Group, { __index = Container })

    local function evalSource(src, opt)
        local v = src.Value
        if opt ~= nil then
            if type(v) == "table" then return v[opt] == true or table.find(v, opt) ~= nil end
            return v == opt
        end
        if type(v) == "table" then return next(v) ~= nil end
        return v ~= nil and v ~= false
    end

    function Group:_effective()
        local parent = self._parent
        local up = true
        if parent ~= nil and parent._effective ~= nil then up = parent:_effective() end
        return self._own and up
    end

    function Group:_refresh()
        local eff = self:_effective()
        for _, c in ipairs(self._members) do
            c._gv[self] = eff
            c:_applyVis()
        end
        for _, g in ipairs(self._children) do g:_refresh() end
    end

    function Group:_make(kind, o)
        local c = self._sec:_make(kind, o)
        if type(c) == "table" and getmetatable(c) ~= Stub then
            self._members[#self._members + 1] = c
            c._gv[self] = self:_effective()
            c:_applyVis()
        end
        return c
    end

    function Group:AddGroup(o)
        return Container.AddGroup(self, o)
    end

    function Group:SetVisible(v)
        self._manual = v ~= false
        self:_refresh()
    end

    function Container:AddGroup(o)
        o = o or {}
        local g = setmetatable({
            _sec = self._sec or self,
            _menu = self._menu,
            _parent = self,
            _src = o.Source,
            _opt = o.Option,
            _own = true,
            _members = {},
            _children = {},
        }, Group)
        if self._children ~= nil then self._children[#self._children + 1] = g end
        local src = o.Source
        if type(src) == "table" and rawget(src, "ValueChanged") ~= nil then
            g._own = evalSource(src, o.Option) and true or false
            local ok, conn = pcall(function()
                return src.ValueChanged:Connect(function()
                    g._own = evalSource(src, g._opt) and true or false
                    g:_refresh()
                end)
            end)
            if ok then
                self._menu._groupConns[#self._menu._groupConns + 1] = conn
            end
        end
        return g
    end

    local Section = {}
    Section.__index = Section
    setmetatable(Section, { __index = Container })

    function Section:_make(kind, o)
        local maker = Makers[kind]
        if maker == nil then return stub end
        return maker(self, o)
    end

    function Section:SetVisible(v)
        local function try()
            local ok, inst = pcall(function() return self._gb.Instance end)
            if ok and typeof(inst) == "Instance" then
                inst.Visible = v ~= false
                return true
            end
            return false
        end
        if not try() then
            task.spawn(function()
                for _ = 1, 120 do
                    task.wait(0.05)
                    if try() then return end
                end
            end)
        end
    end

    local function newSection(page, o)
        o = o or {}
        local tab = page._tab
        local side = o.Side
        local columns = page._columns or 2
        local column = 1
        if columns >= 2 and side == "right" then column = 2 end
        if columns >= 3 and side == "right" then column = 3 end
        local title = o.Title
        if title == nil or tostring(title) == "" then title = " " end
        local sec = setmetatable({ _menu = page._menu, _page = page }, Section)
        sec._sec = sec
        sec._gb = tab:CreateGroupbox({ Name = tostring(title), Column = column, Icon = iconOf(o.Icon) }, uid("gb"))
        return sec
    end

    local Grid = {}
    Grid.__index = Grid
    function Grid:AddSection(o)
        if self._inert then return stub end
        local ok, res = pcall(newSection, self._page, o)
        if ok then return res end
        log("AddSection failed: " .. tostring(res))
        return stub
    end

    local function multiSection(page, o)
        o = o or {}
        local panes = {}
        for i, title in ipairs(o.Titles or {}) do
            local ok, res = pcall(newSection, page, { Title = title, Side = o.Side })
            panes[i] = ok and res or stub
            if not ok then log("AddMultiSection failed: " .. tostring(res)) end
        end
        return table.unpack(panes)
    end
    function Grid:AddMultiSection(o)
        if self._inert then return stub, stub end
        return multiSection(self._page, o)
    end
    function Section:AddMultiSection(o)
        return multiSection(self._page, o)
    end
    function Grid:SetVisible() end

    local Page = {}
    Page.__index = function(t, k)
        local v = rawget(Page, k)
        if v ~= nil then return v end
        if isMethodName(k) then return function() return nil end end
        return nil
    end

    function Page:_ensure(columns)
        if self._tab ~= nil then return self._tab end
        columns = math.max(1, math.min(3, columns or 2))
        self._columns = columns
        self._tab = self._ts:CreateTab({ Name = self.Label, Columns = columns, Icon = iconOf(self.Icon) }, uid("tab"))
        return self._tab
    end

    function Page:Grid(o)
        o = o or {}
        local grid = setmetatable({ _page = self }, Grid)
        if self._theme then
            local tab = self:_ensure(1)
            pcall(function() tab:BuildThemeGroupbox(1) end)
            grid._inert = true
            return grid
        end
        self:_ensure(o.Columns)
        return grid
    end

    function Page:OnFirstOpen(fn)
        if type(fn) ~= "function" then return end
        task.defer(function()
            local ok, err = pcall(fn)
            if not ok then log("page '" .. tostring(self.Label) .. "' failed to build: " .. tostring(err)) end
        end)
    end

    function Page:Open() end
    function Page:SetVisible() end

    local Tab = {}
    Tab.__index = function(t, k)
        local v = rawget(Tab, k)
        if v ~= nil then return v end
