    end
    if _src then
        local fn = loadstring(_src)
        if fn then
            _log("round " .. _round .. ": running the script")
            task.spawn(fn)
            local t0 = tick()
            while tick() - t0 < 120 and (_env.XiaoYuRageMax == nil or _env.XiaoYuRageMax == _before) do
                task.wait(0.5)
            end
            if _env.XiaoYuRageMax ~= nil and _env.XiaoYuRageMax ~= _before then
                _log("script reported in after " .. math.floor(tick() - t0) .. " s")
                return
            end
            _log("round " .. _round .. ": script did not report in within 120 s")
        else
